import { z } from 'zod';

/**
 * CS2 match server (0.23.x → 0.24.0): one PC runs the Counter-Strike 2 dedicated server, the
 * other PCs join it with one click, and staff send the match commands (freezetime, restart,
 * warmup end) from the admin panel over RCON. Everything here is pure data + string building;
 * the PCs do the actual work (see the client's cs2 commands).
 */

export const CS2_APP_ID = 730;
export const CS2_SERVER_LAUNCH_TIMEOUT_MS = 20_000;

/** Passwords are generated by LIKApcs and never typed by staff, so they stay URL/argv-safe. */
const SAFE_SECRET = /^[A-Za-z0-9]{0,64}$/;
const SAFE_MAP = /^[a-z0-9_]{2,40}$/;

export const cs2ConfigSchema = z.object({
  /** The station whose PC runs the CS2 server. null until staff pick one. */
  serverStationId: z.string().min(1).max(64).nullable().default(null),
  /** IPv4 address clients connect to; empty → the server PC's last known LAN address. */
  serverAddress: z
    .string()
    .trim()
    .max(253)
    .regex(/^(\d{1,3}\.){3}\d{1,3}$|^$/, 'Use an IPv4 address such as 192.168.1.10')
    .default(''),
  port: z.number().int().min(1024).max(65535).default(27015),
  map: z
    .string()
    .trim()
    .regex(SAFE_MAP, 'Map names use lowercase letters, digits and underscores')
    .default('de_dust2'),
  maxPlayers: z.number().int().min(2).max(10).default(10),
  /** Join password for players (empty = open LAN server). Generated when staff enable it. */
  playerPassword: z.string().regex(SAFE_SECRET).max(64).default(''),
  /** RCON password for the panel's match commands. Generated on first save. */
  rconPassword: z.string().regex(SAFE_SECRET).max(64).default(''),
});
export type Cs2Config = z.infer<typeof cs2ConfigSchema>;

export const CS2_DEFAULT_CONFIG: Cs2Config = cs2ConfigSchema.parse({});

/** A readable random secret of 16 characters (letters and digits). */
export function generateCs2Secret(length = 16): string {
  const alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789';
  // Rejection sampling keeps every character equally likely (256 is not a multiple of 55).
  const limit = 256 - (256 % alphabet.length);
  let out = '';
  while (out.length < length) {
    const bytes = new Uint8Array(length);
    // Web Crypto exists in browsers, Tauri and Node 20+; typed here because shared has no DOM lib.
    (
      globalThis as unknown as { crypto: { getRandomValues(a: Uint8Array): Uint8Array } }
    ).crypto.getRandomValues(bytes);
    for (const b of bytes) {
      if (b < limit && out.length < length) out += alphabet[b % alphabet.length];
    }
  }
  return out;
}

/** Arguments passed to `cs2.exe` on the server PC (no shell — each entry is one argv item). */
export function cs2ServerArgs(c: Cs2Config): string[] {
  const args = [
    '-dedicated',
    '-usercon', // RCON over the game port
    '-port',
    String(c.port),
    '-maxplayers',
    String(c.maxPlayers),
    '+sv_lan',
    '1', // LAN: no public listing, no GSLT needed
    '+game_type',
    '0',
    '+game_mode',
    '1',
    '+map',
    c.map,
    '+mp_freezetime',
    '3',
    '+mp_warmuptime',
    '30',
  ];
  if (c.playerPassword) args.push('+sv_password', c.playerPassword);
  if (c.rconPassword) args.push('+rcon_password', c.rconPassword);
  return args;
}

/** `steam://` link that starts CS2 on a PC and connects it to the server (one click). */
export function cs2ConnectUrl(address: string, port: number, password: string): string {
  let url = `steam://rungameid/${CS2_APP_ID}//+connect%20${address}:${port}`;
  if (password) url += `%20+password%20${password}`;
  return url;
}

/** Match commands the panel can send. Each preset is one RCON line. */
export const CS2_RCON_PRESETS = {
  freezetime: 'mp_freezetime 3',
  restart: 'mp_restartgame 3',
  warmup_end: 'mp_warmup_end',
} as const;
export type Cs2Preset = keyof typeof CS2_RCON_PRESETS;

/** Commands the server may send to a PC for CS2 (the generic staff route does not accept them). */
export const CS2_STATION_COMMANDS = [
  'cs2.install',
  'cs2.start',
  'cs2.stop',
  'cs2.connect',
] as const;
export type Cs2StationCommand = (typeof CS2_STATION_COMMANDS)[number];

/** Reads the RCON answer shape for the admin page. */
export interface Cs2StatusResponse {
  /** Passwords are never returned; the flags say whether they are set. */
  config: Omit<Cs2Config, 'rconPassword' | 'playerPassword'> & {
    rconPasswordSet: boolean;
    playerPasswordSet: boolean;
  };
  serverStation: { id: string; code: string; name: string; online: boolean } | null;
  /** The address the panel will use (configured, or the server PC's detected LAN address). */
  resolvedAddress: string | null;
}

/** Partial update from the admin page; passwords are never accepted from the request. */
export const cs2ConfigPatchSchema = cs2ConfigSchema
  .omit({ playerPassword: true, rconPassword: true })
  .partial()
  .strict();
export type Cs2ConfigPatch = z.infer<typeof cs2ConfigPatchSchema>;

export const cs2ConnectBodySchema = z.object({
  stationIds: z.array(z.string().min(1).max(64)).min(1).max(60),
});
export const cs2RconBodySchema = z.object({
  preset: z.enum(['freezetime', 'restart', 'warmup_end']),
});

/**
 * The PC accepts only the link LIKApcs builds (`cs2ConnectUrl`): CS2 by app id, one IPv4
 * address, a port and an optional join password. Anything else is refused before Steam sees it.
 */
const CS2_CONNECT_URL =
  /^steam:\/\/rungameid\/730\/\/\+connect%20(\d{1,3}\.){3}\d{1,3}:\d{4,5}(%20\+password%20[A-Za-z0-9]{1,64})?$/;
export function isCs2ConnectUrl(url: string): boolean {
  return CS2_CONNECT_URL.test(url);
}

/** The server launch arguments the PC accepts: CS2 dedicated mode, no shell metacharacters. */
export function isCs2ServerArgs(args: unknown): args is string[] {
  return (
    Array.isArray(args) &&
    args.length > 0 &&
    args.length <= 80 &&
    args[0] === '-dedicated' &&
    args.every((a) => typeof a === 'string' && a.length <= 200 && !/[\r\n\0]/.test(a))
  );
}
